content:
{
  "initial_state": "arrival_and_relaxation",
  "states": [
    {
      "id": "arrival_and_relaxation",
      "description": "The person arrives home, adjusts the climate, and gets a drink.",
      "rules": [
        {
          "trigger": "Person enters through the front door",
          "action": "Operate the air conditioner: turn on at 26°C."
        },
        {
          "trigger": "Person approaches the refrigerator",
          "action": "Take the cola out of the refrigerator and place it next to the person."
        },
        {
          "trigger": "refrigerator door has been open for 1 minute",
          "action": "Operate the refrigerator: close door."
        }
      ],
      "next": [
        {
          "to": "laundry_cycle",
          "on": "washing machine cycle finished"
        }
      ]
    },
    {
      "id": "laundry_cycle",
      "description": "The washing machine finishes and the person transfers laundry to the dryer.",
      "rules": [
        {
          "trigger": "washing machine cycle finished",
          "action": "Take the laundry out of the washing machine and place it inside the dryer."
        },
        {
          "trigger": "dryer door closed",
          "action": "Operate the dryer: start."
        }
      ],
      "next": [
        {
          "to": "kitchen_cleanup",
          "on": "Person approaches the refrigerator"
        }
      ]
    },
    {
      "id": "kitchen_cleanup",
      "description": "The person prepares a drink and cleans up the kitchen items.",
      "rules": [
        {
          "trigger": "Person approaches the refrigerator",
          "action": "Take the milk out of the refrigerator and place it next to the person."
        },
        {
          "trigger": "milk on kitchen counter",
          "action": "Put the milk from the kitchen counter into the refrigerator."
        },
        {
          "trigger": "empty cup on kitchen counter",
          "action": "Put the cup from the kitchen counter into the dishwasher."
        }
      ],
      "next": []
    }
  ]
}
